<?php foreach ( neotecx_products() as $index => $product ) : ?><section class="section container product-detail"><div class="product-copy"><span class="eyebrow"><?php echo esc_html( $product['name'] ); ?></span><h2><?php echo esc_html( $product['desc'] ); ?></h2><p><?php echo esc_html( $product['problem'] ); ?></p><a class="button" href="<?php echo esc_url( home_url( '/products/' . $product['slug'] . '/' ) ); ?>">View product →</a></div><div class="glass feature-grid"><?php foreach ( $product['features'] as $feature ) : ?><div>✓ &nbsp;<?php echo esc_html( $feature ); ?></div><?php endforeach; ?></div></section><?php endforeach; ?>
